"""Normalize an accepted VM event before passing it to the stream store."""

from datetime import datetime, timezone

from .models import EventIn, StoredEvent
from .stream_store import RedisStreamStore


class EventMapper:
    def __init__(self, store: RedisStreamStore) -> None:
        self.store = store

    async def ingest(self, event: EventIn) -> str:
        normalized = StoredEvent(**event.model_dump(), ingested_at=datetime.now(timezone.utc))
        return await self.store.append(normalized)

