import type { Channel } from '../contracts/vega'

export interface TelemetryParticle {
  id: number
  from: string
  to: string
  channel: Channel
  suspicious: boolean
  progress: number // 0..1
  speed: number // progress per second
}

let nextParticleId = 1
const activeParticles: TelemetryParticle[] = []

export const particleBus = {
  spawn(from: string, to: string, channel: Channel, suspicious = false) {
    if (activeParticles.length > 140) {
      activeParticles.shift()
    }
    activeParticles.push({
      id: nextParticleId++,
      from,
      to,
      channel,
      suspicious,
      progress: 0,
      speed: suspicious ? 0.72 : 0.48 + Math.random() * 0.22,
    })
  },

  step(dtSeconds: number): TelemetryParticle[] {
    for (let i = activeParticles.length - 1; i >= 0; i--) {
      const p = activeParticles[i]
      p.progress += p.speed * dtSeconds
      if (p.progress >= 1) {
        activeParticles.splice(i, 1)
      }
    }
    return activeParticles
  },

  clear() {
    activeParticles.length = 0
  },
}

import type { ScenarioId, VegaStage } from '../contracts/vega'
import { SCENARIOS } from '../data/scenarios'
import { useVegaStore } from '../store/useVegaStore'
import type { VegaDataSource } from './dataSource'
import { particleBus } from './particleBus'

class MockScenarioSource implements VegaDataSource {
  readonly mode = 'SIMULATED' as const
  private timerId: number | null = null
  private ambientTimerId: number | null = null
  private containmentTimers: number[] = []
  private emittedEvents = new Set<string>()
  private emittedFindings = new Set<string>()
  private emittedCouncil = false
  private emittedOracle = false
  private emittedWarden = false
  private autoStageEnabled = true

  start(scenarioId: ScenarioId = 'sev1-exfil') {
    this.stop()
    this.resetState(scenarioId)

    this.timerId = window.setInterval(() => {
      const state = useVegaStore.getState()
      if (!state.isPlaying) return

      const nextElapsed = state.elapsedMs + 100 * state.playbackSpeed
      state.setElapsedMs(nextElapsed)
      state.tickTtl(0.1 * state.playbackSpeed)
      this.syncUpTo(nextElapsed, this.autoStageEnabled)
    }, 100)

    this.ambientTimerId = window.setInterval(() => {
      const state = useVegaStore.getState()
      if (!state.isPlaying) return
      const healthyEdges = state.edges.filter((e) => !e.anomalous)
      if (healthyEdges.length === 0) return
      const edge = healthyEdges[Math.floor(Math.random() * healthyEdges.length)]
      const fromNode = state.nodes.find((n) => n.source_id === edge.from)
      if (fromNode?.status === 'isolated') return
      particleBus.spawn(edge.from, edge.to, edge.channel, false)
    }, 320)
  }

  stop() {
    if (this.timerId !== null) {
      window.clearInterval(this.timerId)
      this.timerId = null
    }
    if (this.ambientTimerId !== null) {
      window.clearInterval(this.ambientTimerId)
      this.ambientTimerId = null
    }
    this.clearContainmentTimers()
  }

  reset(scenarioId?: ScenarioId) {
    const target = scenarioId ?? useVegaStore.getState().scenarioId
    this.start(target)
  }

  setPlaying(playing: boolean) {
    useVegaStore.getState().setPlaying(playing)
  }

  setSpeed(multiplier: number) {
    useVegaStore.getState().setPlaybackSpeed(multiplier)
  }

  jumpToStage(stage: VegaStage) {
    const state = useVegaStore.getState()
    if (stage === 'chronos') {
      state.setChronosExpanded(true)
      return
    }
    if (stage === 'observer') {
      state.setObserverOpen(true)
      return
    }

    this.autoStageEnabled = false
    const sc = SCENARIOS[state.scenarioId]

    if (stage === 'panopticon') {
      state.setStage('panopticon')
      return
    }

    if (sc.id === 'benign-control') {
      this.syncUpTo(5000, false)
      state.setElapsedMs(5000)
      state.setStage(stage)
      return
    }

    const targetMsByStage: Record<'ghost_protocol' | 'council' | 'blackout', number> = {
      ghost_protocol: 10000,
      council: 13500,
      blackout: 15500,
    }

    const targetMs = targetMsByStage[stage]
    if (state.elapsedMs < targetMs) {
      this.syncUpTo(targetMs, false)
      state.setElapsedMs(targetMs)
    }

    if (stage === 'ghost_protocol') {
      state.selectNode('vm-a')
      state.setThreatMode('INVESTIGATE')
    } else if (stage === 'council') {
      state.setThreatMode('INVESTIGATE')
    } else if (stage === 'blackout') {
      if (state.wardenDecision?.execution_status !== 'contained_dry_run') {
        state.setThreatMode('SEV1_ESCALATION')
      }
    }

    state.setStage(stage)
  }

  injectAnomaly() {
    const state = useVegaStore.getState()
    if (state.scenarioId !== 'sev1-exfil') {
      this.reset('sev1-exfil')
    }
    this.autoStageEnabled = true
    const jumpMs = 4500
    this.syncUpTo(jumpMs, false)
    useVegaStore.getState().setElapsedMs(jumpMs)
    useVegaStore.getState().setPlaying(true)
    useVegaStore.getState().selectNode('vm-a')
    useVegaStore.getState().setStage('ghost_protocol')
  }

  authorizeContainment() {
    const state = useVegaStore.getState()
    const sc = SCENARIOS[state.scenarioId]
    if (!state.wardenDecision || state.wardenDecision.execution_status === 'contained_dry_run') {
      return
    }

    this.clearContainmentTimers()
    state.updateWardenExecution({
      approval_status: 'approved',
      approval_ref: 'APR-DEMO-1042',
      execution_status: 'executing',
    })

    const steps = sc.containmentSteps ?? []
    steps.forEach((step, idx) => {
      const t = window.setTimeout(() => {
        const current = useVegaStore.getState()
        current.appendWardenAudit(step)
        if (idx === 2) {
          current.updateNodeStatus('vm-a', 'isolated')
          current.markEdgeAnomalous('e-core-a', false)
          current.markEdgeAnomalous('e-a-b', false)
        }
        if (idx === steps.length - 1) {
          current.updateWardenExecution({ execution_status: 'contained_dry_run' })
          current.setThreatMode('CONTAINED')
        }
      }, idx * 420)
      this.containmentTimers.push(t)
    })
  }

  denyContainment() {
    const state = useVegaStore.getState()
    if (!state.wardenDecision) return
    this.clearContainmentTimers()
    state.updateWardenExecution({
      approval_status: 'denied',
      execution_status: 'denied',
    })
    state.appendWardenAudit({
      id: `aud-deny-${Date.now()}`,
      timestamp: new Date().toISOString().slice(11, 23) + 'Z',
      actor: 'OPERATOR',
      message: 'Containment request denied by operator. Monitoring continues in SEV1 review.',
      status: 'warn',
    })
  }

  askObserver(prompt: string) {
    const trimmed = prompt.trim()
    if (!trimmed) return
    const state = useVegaStore.getState()
    const sc = SCENARIOS[state.scenarioId]
    const now = new Date().toISOString().slice(11, 19) + 'Z'

    state.addObserverMessage({
      id: `usr-${Date.now()}`,
      role: 'user',
      text: trimmed,
      timestamp: now,
    })

    const lower = trimmed.toLowerCase()
    let matched = sc.observerPresets[0]

    if (lower.includes('backup') || lower.includes('false') || lower.includes('routine') || lower.includes('ci')) {
      matched = sc.observerPresets.find((p) => p.id.includes('false') || p.id.includes('benign')) ?? matched
    } else if (lower.includes('privacy') || lower.includes('ttl') || lower.includes('redis') || lower.includes('identity')) {
      matched = sc.observerPresets.find((p) => p.id.includes('privacy')) ?? matched
    } else if (lower.includes('why') || lower.includes('042') || lower.includes('vm-a') || lower.includes('flag')) {
      matched = sc.observerPresets[0]
    }

    window.setTimeout(() => {
      useVegaStore.getState().addObserverMessage({
        id: `vega-${Date.now()}`,
        role: 'vega',
        text: matched.answer,
        qa: matched,
        timestamp: new Date().toISOString().slice(11, 19) + 'Z',
      })
    }, 260)
  }

  private resetState(scenarioId: ScenarioId) {
    this.emittedEvents.clear()
    this.emittedFindings.clear()
    this.emittedCouncil = false
    this.emittedOracle = false
    this.emittedWarden = false
    this.autoStageEnabled = true
    particleBus.clear()
    useVegaStore.getState().loadScenario(scenarioId)
  }

  private clearContainmentTimers() {
    this.containmentTimers.forEach((id) => window.clearTimeout(id))
    this.containmentTimers = []
  }

  private syncUpTo(elapsedMs: number, allowAutoStage: boolean) {
    const state = useVegaStore.getState()
    const sc = SCENARIOS[state.scenarioId]

    // Window transitions
    if (sc.id === 'sev1-exfil') {
      if (elapsedMs >= 4200 && state.activeWindowId !== 'W-1042') {
        state.updateWindowStatus('W-1041', 'clean')
        state.setActiveWindowId('W-1042')
        state.updateWindowStatus('W-1042', 'scouting')
      }
    } else if (elapsedMs >= 3800) {
      state.updateWindowStatus('W-1043', 'clean')
    }

    // Events
    for (const item of sc.events) {
      if (elapsedMs >= item.offsetMs && !this.emittedEvents.has(item.event.event_id)) {
        this.emittedEvents.add(item.event.event_id)
        state.pushEvent(item.event)

        if (item.edgeId) {
          const edge = state.edges.find((e) => e.id === item.edgeId)
          if (edge) {
            particleBus.spawn(edge.from, edge.to, item.event.channel, Boolean(item.event.suspicious))
            if (item.event.suspicious) {
              state.markEdgeAnomalous(edge.id, true)
            }
          }
        }

        if (item.event.suspicious) {
          state.updateNodeStatus(item.event.source_id, 'elevated')
          if (allowAutoStage && state.stage === 'panopticon') {
            state.selectNode('vm-a')
            state.setThreatMode('INVESTIGATE')
            state.setStage('ghost_protocol')
          }
        }
      }
    }

    // Scout findings
    for (const item of sc.findings) {
      if (elapsedMs >= item.offsetMs && !this.emittedFindings.has(item.finding.finding_id)) {
        this.emittedFindings.add(item.finding.finding_id)
        state.pushFinding(item.finding)
      }
    }

    // Council signal
    if (sc.councilSignal && elapsedMs >= sc.councilSignal.offsetMs && !this.emittedCouncil) {
      this.emittedCouncil = true
      state.setCouncilSignal(sc.councilSignal.signal)
      state.updateWindowStatus('W-1042', 'flagged')
      state.updateNodeStatus('vm-a', 'compromised')
      state.setThreatMode('INVESTIGATE')
      if (allowAutoStage && state.stage === 'ghost_protocol') {
        state.setStage('council')
      }
    }

    // Oracle assessment
    if (sc.oracleAssessment && elapsedMs >= sc.oracleAssessment.offsetMs && !this.emittedOracle) {
      this.emittedOracle = true
      state.setOracleAssessment(sc.oracleAssessment.assessment)
    }

    // Warden decision -> SEV1 Blackout
    if (sc.wardenDecision && elapsedMs >= sc.wardenDecision.offsetMs && !this.emittedWarden) {
      this.emittedWarden = true
      state.setWardenDecision(structuredClone(sc.wardenDecision.decision))
      state.setThreatMode('SEV1_ESCALATION')
      if (allowAutoStage && state.stage === 'council') {
        state.setStage('blackout')
      }
    }
  }
}

export const vegaSource: VegaDataSource = new MockScenarioSource()

import { Activity, Clock, Command, Lock, Radio, ShieldAlert, SlidersHorizontal } from 'lucide-react'
import { motion } from 'motion/react'
import type { VegaStage } from '../../contracts/vega'
import { vegaSource } from '../../engine/mockSource'
import { useVegaStore } from '../../store/useVegaStore'

const STAGE_ITEMS: Array<{ id: VegaStage; num: string; label: string; owner: string }> = [
  { id: 'panopticon', num: '01', label: 'PANOPTICON', owner: 'SENTINEL' },
  { id: 'ghost_protocol', num: '02', label: 'GHOST PROTOCOL', owner: 'SENTINEL' },
  { id: 'council', num: '03', label: 'THE COUNCIL', owner: 'ORACLE' },
  { id: 'chronos', num: '04', label: 'CHRONOS', owner: 'ORACLE' },
  { id: 'blackout', num: '05', label: 'BLACKOUT', owner: 'WARDEN' },
  { id: 'observer', num: '06', label: 'OBSERVER', owner: 'CORE' },
]

function formatTtl(seconds: number): string {
  const s = Math.max(0, Math.floor(seconds))
  const mins = Math.floor(s / 60)
  const rem = s % 60
  return `${String(mins).padStart(2, '0')}:${String(rem).padStart(2, '0')}`
}

export function TopHud() {
  const stage = useVegaStore((s) => s.stage)
  const threatMode = useVegaStore((s) => s.threatMode)
  const activeWindowId = useVegaStore((s) => s.activeWindowId)
  const ttlSecondsRemaining = useVegaStore((s) => s.ttlSecondsRemaining)
  const councilSignal = useVegaStore((s) => s.councilSignal)
  const chronosExpanded = useVegaStore((s) => s.chronosExpanded)
  const observerOpen = useVegaStore((s) => s.observerOpen)
  const presenterOpen = useVegaStore((s) => s.presenterOpen)
  const setPresenterOpen = useVegaStore((s) => s.setPresenterOpen)
  const dataMode = useVegaStore((s) => s.dataMode)

  const threatBadgeClass =
    threatMode === 'WATCH'
      ? 'border-sky-400/40 bg-sky-500/10 text-sky-300'
      : threatMode === 'INVESTIGATE'
        ? 'border-purple-400/40 bg-purple-500/15 text-purple-300'
        : threatMode === 'CONTAINED'
          ? 'border-emerald-400/40 bg-emerald-500/15 text-emerald-300'
          : 'border-red-500/60 bg-red-500/20 text-red-300 animate-pulse'

  return (
    <header className="relative z-30 flex h-14 shrink-0 items-center justify-between border-b border-slate-800/80 bg-[#060a14]/90 px-4 backdrop-blur-md">
      {/* Brand + Simulation Guardrail */}
      <div className="flex items-center gap-3">
        <div className="flex items-center gap-2">
          <span
            className="inline-block h-2.5 w-2.5 rounded-full shadow-[0_0_12px_var(--vega-accent)]"
            style={{ backgroundColor: 'var(--vega-accent)' }}
          />
          <span className="text-sm font-bold tracking-[0.22em] text-slate-100">VEGA</span>
        </div>

        <span className="hidden items-center gap-1.5 rounded border border-amber-400/30 bg-amber-500/10 px-2 py-0.5 font-mono-tabular text-[10px] font-medium tracking-wider text-amber-300 xl:inline-flex">
          <Radio className="h-3 w-3" />
          {dataMode} • DRY-RUN
        </span>
      </div>

      {/* 6-Stage Narrative Switcher */}
      <nav className="flex items-center gap-1 rounded-lg border border-slate-800/90 bg-slate-950/70 p-1">
        {STAGE_ITEMS.map((item) => {
          const isActive =
            item.id === 'chronos'
              ? chronosExpanded
              : item.id === 'observer'
                ? observerOpen
                : stage === item.id

          return (
            <button
              key={item.id}
              type="button"
              onClick={() => vegaSource.jumpToStage(item.id)}
              className={`relative flex items-center gap-1.5 rounded-md px-2.5 py-1 text-[11px] font-medium tracking-wider transition-colors ${
                isActive ? 'text-white' : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              {isActive && (
                <motion.span
                  layoutId="vega-stage-pill"
                  transition={{ type: 'spring', stiffness: 420, damping: 34 }}
                  className="absolute inset-0 rounded-md border border-white/15 bg-white/10"
                />
              )}
              <span className="relative font-mono-tabular text-[10px] text-slate-400">
                {item.num}
              </span>
              <span className="relative hidden md:inline">{item.label}</span>
            </button>
          )
        })}
      </nav>

      {/* Telemetry Status + Quick Triggers */}
      <div className="flex items-center gap-2.5">
        <div className="hidden items-center gap-2 rounded border border-slate-800 bg-slate-900/70 px-2.5 py-1 font-mono-tabular text-[11px] text-slate-300 lg:flex">
          <Activity className="h-3.5 w-3.5 text-sky-400" />
          <span>{activeWindowId}</span>
          <span className="text-slate-600">|</span>
          <Clock className="h-3.5 w-3.5 text-slate-400" />
          <span>TTL {formatTtl(ttlSecondsRemaining)}</span>
          {councilSignal?.snapshot_preserved && (
            <span className="ml-1 inline-flex items-center gap-1 rounded bg-emerald-500/15 px-1.5 py-0.5 text-[10px] text-emerald-300">
              <Lock className="h-2.5 w-2.5" />
              SNAPSHOT
            </span>
          )}
        </div>

        <div
          className={`flex items-center gap-1.5 rounded border px-2.5 py-1 font-mono-tabular text-[11px] font-semibold tracking-wider ${threatBadgeClass}`}
        >
          <ShieldAlert className="h-3.5 w-3.5" />
          <span>{threatMode}</span>
        </div>

        <button
          type="button"
          onClick={() => vegaSource.jumpToStage('observer')}
          title="Open Observer (Cmd/Ctrl+K)"
          className="hidden items-center gap-1 rounded border border-slate-700/80 bg-slate-900/80 px-2 py-1 font-mono-tabular text-[11px] text-slate-300 transition hover:border-sky-400/50 hover:text-white sm:flex"
        >
          <Command className="h-3 w-3" />
          <span>K</span>
        </button>

        <button
          type="button"
          onClick={() => setPresenterOpen(!presenterOpen)}
          title="Presenter Cue Controls (Shift+D)"
          className={`rounded border p-1.5 transition ${
            presenterOpen
              ? 'border-sky-400/60 bg-sky-500/15 text-sky-300'
              : 'border-slate-800 bg-slate-900/70 text-slate-400 hover:text-slate-200'
          }`}
        >
          <SlidersHorizontal className="h-3.5 w-3.5" />
        </button>
      </div>
    </header>
  )
}

import { FastForward, Pause, Play, RotateCcw, ShieldCheck, Zap } from 'lucide-react'
import { AnimatePresence, motion } from 'motion/react'
import { vegaSource } from '../../engine/mockSource'
import { useVegaStore } from '../../store/useVegaStore'

export function PresenterBar() {
  const presenterOpen = useVegaStore((s) => s.presenterOpen)
  const isPlaying = useVegaStore((s) => s.isPlaying)
  const playbackSpeed = useVegaStore((s) => s.playbackSpeed)
  const scenarioId = useVegaStore((s) => s.scenarioId)

  return (
    <AnimatePresence>
      {presenterOpen && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          transition={{ duration: 0.18 }}
          className="vega-panel fixed top-16 right-4 z-40 flex flex-wrap items-center gap-2 rounded-xl px-3 py-2 text-xs"
        >
          <span className="font-mono-tabular text-[10px] font-semibold tracking-widest text-slate-400 uppercase">
            Presenter Cues
          </span>

          <div className="h-4 w-px bg-slate-800" />

          <button
            type="button"
            onClick={() => vegaSource.setPlaying(!isPlaying)}
            className="inline-flex items-center gap-1 rounded-md border border-slate-700 bg-slate-900 px-2 py-1 text-slate-200 hover:border-sky-400/50"
          >
            {isPlaying ? <Pause className="h-3 w-3" /> : <Play className="h-3 w-3" />}
