import { FastForward, Pause, Play, RotateCcw, ShieldCheck, Zap } from 'lucide-react'
import { AnimatePresence, motion } from 'motion/react'
import { vegaSource } from '../../engine/mockSource'
import { useVegaStore } from '../../store/useVegaStore'

export function PresenterBar() {
  const presenterOpen = useVegaStore((s) => s.presenterOpen)
  const isPlaying = useVegaStore((s) => s.isPlaying)
  const playbackSpeed = useVegaStore((s) => s.playbackSpeed)
  const scenarioId = useVegaStore((s) => s.scenarioId)

  return (
    <AnimatePresence>
      {presenterOpen && (
        <motion.div
          initial={{ opacity: 0, y: -10 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -10 }}
          transition={{ duration: 0.18 }}
          className="vega-panel fixed top-16 right-4 z-40 flex flex-wrap items-center gap-2 rounded-xl px-3 py-2 text-xs"
        >
          <span className="font-mono-tabular text-[10px] font-semibold tracking-widest text-slate-400 uppercase">
            Presenter Cues
          </span>

          <div className="h-4 w-px bg-slate-800" />

          <button
            type="button"
            onClick={() => vegaSource.setPlaying(!isPlaying)}
            className="inline-flex items-center gap-1 rounded-md border border-slate-700 bg-slate-900 px-2 py-1 text-slate-200 hover:border-sky-400/50"
          >
            {isPlaying ? <Pause className="h-3 w-3" /> : <Play className="h-3 w-3" />}
            <span>{isPlaying ? 'Pause' : 'Play'}</span>
          </button>

          <div className="flex items-center gap-1 rounded-md border border-slate-800 bg-slate-950 p-0.5 font-mono-tabular text-[11px]">
            {[1, 2, 4].map((spd) => (
              <button
                key={spd}
                type="button"
                onClick={() => vegaSource.setSpeed(spd)}
                className={`rounded px-1.5 py-0.5 transition ${
                  playbackSpeed === spd
                    ? 'bg-sky-500/20 text-sky-300'
                    : 'text-slate-400 hover:text-slate-200'
                }`}
              >
                {spd}x
              </button>
            ))}
          </div>

          <button
            type="button"
            onClick={() => vegaSource.injectAnomaly()}
            className="inline-flex items-center gap-1 rounded-md border border-red-500/40 bg-red-500/15 px-2.5 py-1 font-medium text-red-200 hover:bg-red-500/25"
          >
            <Zap className="h-3 w-3" />
            <span>Inject SEV1 Anomaly</span>
          </button>

          <button
            type="button"
            onClick={() => vegaSource.reset('benign-control')}
            className={`inline-flex items-center gap-1 rounded-md border px-2.5 py-1 font-medium transition ${
              scenarioId === 'benign-control'
                ? 'border-emerald-400/50 bg-emerald-500/20 text-emerald-200'
                : 'border-slate-700 bg-slate-900 text-slate-300 hover:border-emerald-400/40'
            }`}
          >
            <ShieldCheck className="h-3 w-3" />
            <span>Benign Control</span>
          </button>

          <button
            type="button"
            onClick={() => vegaSource.reset('sev1-exfil')}
            className="inline-flex items-center gap-1 rounded-md border border-slate-700 bg-slate-900 px-2 py-1 text-slate-300 hover:border-sky-400/50"
          >
            <RotateCcw className="h-3 w-3" />
            <span>Reset SEV1</span>
          </button>

          <button
            type="button"
            onClick={() => vegaSource.jumpToStage('blackout')}
            className="inline-flex items-center gap-1 rounded-md border border-purple-500/40 bg-purple-500/15 px-2 py-1 text-purple-200 hover:bg-purple-500/25"
          >
            <FastForward className="h-3 w-3" />
            <span>Skip to Blackout</span>
          </button>
        </motion.div>
      )}
    </AnimatePresence>
  )
}

