import { Activity, Clock, Command, Lock, Radio, ShieldAlert, SlidersHorizontal } from 'lucide-react'
import { motion } from 'motion/react'
import type { VegaStage } from '../../contracts/vega'
import { vegaSource } from '../../engine/mockSource'
import { useVegaStore } from '../../store/useVegaStore'

const STAGE_ITEMS: Array<{ id: VegaStage; num: string; label: string; owner: string }> = [
  { id: 'panopticon', num: '01', label: 'PANOPTICON', owner: 'SENTINEL' },
  { id: 'ghost_protocol', num: '02', label: 'GHOST PROTOCOL', owner: 'SENTINEL' },
  { id: 'council', num: '03', label: 'THE COUNCIL', owner: 'ORACLE' },
  { id: 'chronos', num: '04', label: 'CHRONOS', owner: 'ORACLE' },
  { id: 'blackout', num: '05', label: 'BLACKOUT', owner: 'WARDEN' },
  { id: 'observer', num: '06', label: 'OBSERVER', owner: 'CORE' },
]

function formatTtl(seconds: number): string {
  const s = Math.max(0, Math.floor(seconds))
  const mins = Math.floor(s / 60)
  const rem = s % 60
  return `${String(mins).padStart(2, '0')}:${String(rem).padStart(2, '0')}`
}

export function TopHud() {
  const stage = useVegaStore((s) => s.stage)
  const threatMode = useVegaStore((s) => s.threatMode)
  const activeWindowId = useVegaStore((s) => s.activeWindowId)
  const ttlSecondsRemaining = useVegaStore((s) => s.ttlSecondsRemaining)
  const councilSignal = useVegaStore((s) => s.councilSignal)
  const chronosExpanded = useVegaStore((s) => s.chronosExpanded)
  const observerOpen = useVegaStore((s) => s.observerOpen)
  const presenterOpen = useVegaStore((s) => s.presenterOpen)
  const setPresenterOpen = useVegaStore((s) => s.setPresenterOpen)
