"""StreamStore protocol plus InMemory and Redis Streams implementations."""

from __future__ import annotations

from collections import defaultdict
from datetime import datetime, timedelta, timezone
from typing import Protocol

from redis.asyncio import Redis
from redis.exceptions import RedisError

from ..models import Channel, StoredEvent, Window

CHANNELS: tuple[Channel, ...] = ("file", "network", "process")


class StreamStoreUnavailable(Exception):
    """Raised when the backing stream store cannot accept reads or writes."""


class StreamStore(Protocol):
    """Abstract boundary between VEGA ingest/swarm and the ephemeral stream backend."""

    def stream_key(self, channel: Channel) -> str: ...

    async def append(self, event: StoredEvent) -> str: ...

    async def read_window(
        self, window: Window
    ) -> dict[tuple[str, Channel], list[StoredEvent]]: ...

    async def trim_expired(self, retention_seconds: int) -> int: ...

    async def reset_demo_streams(self) -> None: ...

    async def health(self) -> bool: ...


class InMemoryStreamStore:
    """Zero-dependency StreamStore matching Redis Streams windowing and TTL semantics."""

    def __init__(self) -> None:
        self._streams: dict[Channel, list[tuple[str, StoredEvent]]] = {
            ch: [] for ch in CHANNELS
        }
        self._seq = 0

    def stream_key(self, channel: Channel) -> str:
        return f"vega:events:{channel}"

    async def append(self, event: StoredEvent) -> str:
        ms = int(event.ingested_at.timestamp() * 1000)
        stream_id = f"{ms}-{self._seq}"
        self._seq += 1
        self._streams[event.channel].append((stream_id, event))
        return stream_id

    async def read_window(
        self, window: Window
    ) -> dict[tuple[str, Channel], list[StoredEvent]]:
        grouped: dict[tuple[str, Channel], list[StoredEvent]] = defaultdict(list)
        for channel in CHANNELS:
            for _stream_id, event in self._streams[channel]:
                if window.start <= event.ingested_at < window.end:
                    grouped[(event.source_id, channel)].append(event)
        return dict(grouped)

    async def trim_expired(self, retention_seconds: int) -> int:
        cutoff = datetime.now(timezone.utc) - timedelta(seconds=retention_seconds)
        removed = 0
        for channel in CHANNELS:
            before = len(self._streams[channel])
            self._streams[channel] = [
                (sid, ev) for sid, ev in self._streams[channel] if ev.ingested_at >= cutoff
            ]
            removed += before - len(self._streams[channel])
        return removed

    async def reset_demo_streams(self) -> None:
        for channel in CHANNELS:
            self._streams[channel].clear()

    async def health(self) -> bool:
        return True


class RedisStreamStore:
    """Redis Streams implementation using XADD, XRANGE, and exact XTRIM MINID."""

    def __init__(self, redis_url: str) -> None:
        self._client: Redis = Redis.from_url(redis_url, decode_responses=True)

    def stream_key(self, channel: Channel) -> str:
        return f"vega:events:{channel}"

    async def append(self, event: StoredEvent) -> str:
        key = self.stream_key(event.channel)
        try:
            stream_id = await self._client.xadd(key, {"data": event.model_dump_json()})
            return str(stream_id)
        except RedisError as exc:
            raise StreamStoreUnavailable("Redis XADD failed") from exc

    async def read_window(
        self, window: Window
    ) -> dict[tuple[str, Channel], list[StoredEvent]]:
        grouped: dict[tuple[str, Channel], list[StoredEvent]] = defaultdict(list)
        start_ms = max(0, int(window.start.timestamp() * 1000) - 1000)
        end_ms = int(window.end.timestamp() * 1000) + 1000

        try:
            for channel in CHANNELS:
                entries = await self._client.xrange(
                    self.stream_key(channel),
                    min=f"{start_ms}-0",
                    max=f"{end_ms}-999999",
                )
                for _entry_id, fields in entries:
                    raw = fields.get("data")
                    if not raw:
                        continue
                    event = StoredEvent.model_validate_json(raw)
                    if window.start <= event.ingested_at < window.end:
                        grouped[(event.source_id, channel)].append(event)
        except RedisError as exc:
            raise StreamStoreUnavailable("Redis XRANGE failed") from exc

        return dict(grouped)

    async def trim_expired(self, retention_seconds: int) -> int:
        cutoff = datetime.now(timezone.utc) - timedelta(seconds=retention_seconds)
        cutoff_ms = max(0, int(cutoff.timestamp() * 1000))
        trimmed_total = 0
        try:
            for channel in CHANNELS:
                trimmed = await self._client.xtrim(
                    self.stream_key(channel),
                    minid=f"{cutoff_ms}-0",
                    approximate=False,
                )
                trimmed_total += int(trimmed)
        except RedisError as exc:
            raise StreamStoreUnavailable("Redis XTRIM failed") from exc
        return trimmed_total

    async def reset_demo_streams(self) -> None:
        keys = [self.stream_key(ch) for ch in CHANNELS]
        try:
            await self._client.delete(*keys)
        except RedisError as exc:
            raise StreamStoreUnavailable("Redis DELETE failed") from exc

    async def health(self) -> bool:
        try:
            return bool(await self._client.ping())
        except RedisError:
            return False

    async def close(self) -> None:
        await self._client.aclose()

"""Structured LLM reasoning abstraction for Sentinel scouts and Correlator."""

from __future__ import annotations

import json
import re
from typing import Any, Protocol, TypeVar

from google import genai
from google.genai import types
from pydantic import BaseModel

T = TypeVar("T", bound=BaseModel)


class StructuredReasoner(Protocol):
    mode_name: str

    async def generate(
        self,
        *,
        system_instruction: str,
        prompt: str,
        response_schema: type[T],
    ) -> T: ...


class GeminiStructuredReasoner:
    """Async Gemini API reasoner using google-genai structured JSON outputs."""

    def __init__(self, *, api_key: str, model: str) -> None:
        self.mode_name = f"gemini:{model}"
        self._model = model
        self._client = genai.Client(api_key=api_key)

    async def generate(
        self,
        *,
        system_instruction: str,
        prompt: str,
        response_schema: type[T],
    ) -> T:
        response = await self._client.aio.models.generate_content(
            model=self._model,
            contents=prompt,
            config=types.GenerateContentConfig(
                system_instruction=system_instruction,
                response_mime_type="application/json",
                response_schema=response_schema,
                temperature=0.1,
            ),
        )
        parsed = getattr(response, "parsed", None)
        if isinstance(parsed, response_schema):
            return parsed
        if isinstance(parsed, dict):
            return response_schema.model_validate(parsed)
        text = getattr(response, "text", None) or "{}"
        return response_schema.model_validate_json(text)


class HeuristicStructuredReasoner:
    """Offline deterministic fallback when GEMINI_API_KEY is not configured."""

    mode_name = "heuristic-fallback"

    async def generate(
        self,
        *,
        system_instruction: str,
        prompt: str,
        response_schema: type[T],
    ) -> T:
        data = json.loads(prompt)
        schema_name = response_schema.__name__

        if schema_name == "ScoutChunkOutput":
            return response_schema.model_validate(self._analyze_scout_chunk(data))
        if schema_name == "CorrelatorOutput":
            return response_schema.model_validate(self._correlate_findings(data))
        raise ValueError(f"Unsupported schema for HeuristicStructuredReasoner: {schema_name}")

    def _analyze_scout_chunk(self, data: dict[str, Any]) -> dict[str, Any]:
        channel = data.get("channel", "")
        events: list[dict[str, Any]] = data.get("events", [])
        findings: list[dict[str, Any]] = []

        if channel == "file":
            matched_ids = [
                ev["event_id"]
                for ev in events
                if self._matches(
                    ev.get("payload", {}),
                    r"(/srv/secrets|vault-export|hidden_dotfile|\.cache-bundle|read_burst)",
                )
            ]
            if matched_ids:
                findings.append(
                    {
                        "signal": "sensitive_staging_archive",
                        "rationale": (
                            "Detected restricted secret directory access or hidden archive staging "
                            "in temporary storage."
                        ),
                        "evidence_event_ids": matched_ids,
                        "confidence": "high",
                    }
                )

        elif channel == "process":
            matched_ids = [
                ev["event_id"]
                for ev in events
                if self._matches(
                    ev.get("payload", {}),
                    r"(tar\s+-c|/srv/secrets|\.tar\.gz|base64|nc\s+-e)",
                )
            ]
            if matched_ids:
                findings.append(
                    {
                        "signal": "anomalous_archive_command",
                        "rationale": (
                            "Observed interactive shell archiving restricted paths into a hidden "
                            "temporary bundle."
                        ),
                        "evidence_event_ids": matched_ids,
                        "confidence": "high",
                    }
                )

        elif channel == "network":
            matched_ids = [
                ev["event_id"]
                for ev in events
                if self._matches(
                    ev.get("payload", {}),
                    r"(198\.51\.100\.|egress-drop|UNTRUSTED|rejected)",
                )
                or (
                    isinstance(ev.get("payload", {}).get("bytes_out"), (int, float))
                    and ev["payload"]["bytes_out"] >= 25_000_000
                    and not ev.get("payload", {}).get("internal", False)
                )
            ]
            if matched_ids:
                findings.append(
                    {
                        "signal": "unapproved_external_egress_and_probe",
                        "rationale": (
                            "Detected large outbound transfer to an untrusted external ASN or "
                            "rejected lateral SSH probe."
                        ),
                        "evidence_event_ids": matched_ids,
                        "confidence": "high",
                    }
                )

        return {"findings": findings}

    def _correlate_findings(self, data: dict[str, Any]) -> dict[str, Any]:
        findings: list[dict[str, Any]] = data.get("findings", [])
        if not findings:
            return {
                "should_escalate": False,
                "severity": "LOW",
                "summary": "No suspicious findings in window.",
                "rationale": "All channel scouts returned empty findings.",
                "source_ids": [],
                "finding_refs": [],
                "evidence_event_ids": [],
                "escalation_rule": "NONE",
            }

        channels = {f["channel"] for f in findings}
        sources = sorted({f["source_id"] for f in findings})
        finding_refs = [f["finding_id"] for f in findings]
        evidence_ids: list[str] = []
        for f in findings:
            for eid in f.get("evidence_event_ids", []):
                if eid not in evidence_ids:
                    evidence_ids.append(eid)

        multi_channel = len(channels) >= 2
        high_conf = any(f.get("confidence") == "high" for f in findings)
        should_escalate = multi_channel or (high_conf and len(findings) >= 2)

        return {
            "should_escalate": should_escalate,
            "severity": "SEV1" if multi_channel else "HIGH",
            "summary": (
                f"Correlated multi-channel threat activity across {', '.join(sorted(channels))} "
                f"on {', '.join(sources)}"
            ),
            "rationale": (
                f"Combined {len(findings)} scout findings across {len(channels)} channels "
                f"({', '.join(sorted(channels))}) citing {len(evidence_ids)} preserved events."
            ),
            "source_ids": sources,
            "finding_refs": finding_refs,
            "evidence_event_ids": evidence_ids,
            "escalation_rule": (
                "RULE-EXFIL-MULTI-CHANNEL-01" if multi_channel else "RULE-SINGLE-CHANNEL-HIGH-02"
            ),
        }

    @staticmethod
    def _matches(payload: dict[str, Any], pattern: str) -> bool:
        serialized = json.dumps(payload, sort_keys=True)
        return bool(re.search(pattern, serialized, re.IGNORECASE))

